.01287376,-0.015052397,0.031821296,-0.03314168,-0.043836802,0.024163058,0.049118347,-0.020465977,0.026011597,-0.016768897,0.018221322,-0.027860137,0.004208729,0.0057436777,0.013665992,-0.0016669868,0.06654744,0.001006794,-0.0022611604,0.04885427,-0.006634938,-0.004687369,0.020862093,0.0076582367,0.015844628,-0.016768897,0.025615482,0.011487355,-0.013203857,0.055720273,0.0005652901,0.020862093,-0.011289298,-0.05704066,-0.028916446,-0.019805785,0.046213496,-0.056776583,-0.02495529,0.02218248,0.0496465,-0.011751432,0.022578595,-0.035650413,0.0043572728,-0.038027108,0.048062038,0.024163058,-0.009638815,0.04410088,0.040403802,-0.041988265,-0.067603745,0.016306764,-0.005347562,-0.0014111622,0.0137320105,-0.008120372,0.026407713,0.013599972,0.042516418,-0.019013554,-0.033801872,-0.0037961088,-0.019805785,0.029312562,0.002657276,-0.02482325,-0.007823285,0.00825241,-0.002195141,-0.002937858,0.010166969,-0.013203857,0.0496465,0.065227054,-0.015184435,-0.019145591,0.065227054,-0.046477575,-0.05334358,0.00458834,-0.0328776,0.020598017,0.020201901,-0.015184435,0.040139724,0.005974745,-0.038027108,0.031161102,0.017032975,0.041988265,0.06390666,0.09189884,-0.042780496,0.025879558,0.0027067906,-0.029708678,0.0016009676,-0.023634903,-0.034858182,-0.025483442,-0.0024757232,-0.019541707,0.008978622,-0.009308719,0.037234876,0.058625124,-0.008846584,-0.025483442,-0.025483442,0.021786364,0.022446556,0.00208786,-0.008912603,-0.037234876,-0.045685343,0.042780496,-0.02574752,-0.022446556,-0.030104794,-0.0023436844,-0.033537794,0.025879558,0.03670672,0.010431047,-0.008516488,-0.0024757232,0.03961157,-0.0063708606,0.023106748,-0.002195141,0.014326184,-0.028916446,-0.054663967,0.098236695,-0.059417356,-0.017429091,-0.0051164944,-0.017429091,-0.03855526,-0.0123456055,-0.0022446555,0.039083414,-0.039347492,0.04885427,0.011421336,0.008450468,0.0034495075,0.005149504,-0.019145591,-0.042780496,-0.010827162,-0.03961157,-0.03208537,0.03961157,0.044629034,-0.025483442,0.053871736,-0.0010480561,0.02746