,-0.0037387712,0.0061895447,-0.046081696,-0.0015742194,-0.05495457,-0.024615068,0.00751332,-0.039212376,-0.042647038,-0.0038639933,0.034346607,-0.021037297,0.011878202,-0.008550874,0.0055813235,0.0145257525,0.049516357,0.017173303,-0.016386194,-0.008264652,0.021895962,0.0036135493,-0.03334483,-0.025473733,0.0072628763,0.05638568,0.037495047,0.0065830997,0.035920825,-0.031341277,0.0041144374,-0.03663638,0.014311086,0.062110115,0.019033745,-0.0066188774,-0.01989241,0.022468405,-0.03177061,-0.027334174,0.020751074,0.08128697,0.01831819,0.027334174,0.053809684,0.026332399,-0.011234202,-0.04321948,0.010375537,0.0037387712,0.008980206,0.050661243,0.01831819,-0.0050446577,0.017101748,-0.013523976,-0.02160974,0.012307534,-0.014668863,0.030196391,-0.015599084,-0.017030193,0.021180408,0.027047953,-0.006690433,-0.046367917,0.009373762,-0.009659983,0.041215926,0.0061895447,0.017602636,-0.0316275,-0.0006216378,-0.030482613,0.0069408766,-0.06668966,-0.022754626,0.008443541,0.016314639,-0.00704821,-0.04837147,-0.044078145,0.05151991,-0.023040848,-0.046940364,0.017960412,0.030911947,0.022182183,0.0072628763,0.036922604,0.010303982,0.011234202,-0.008908651,0.04779903,0.04321948,0.024471957,-0.0025223289,0.034346607,-0.054382127,0.08414919,0.0032378833,-0.0316275,0.042647038,-0.022182183,-0.032343056,-0.021323519,0.018747523,-0.030768836,-0.0057959897,-0.013523976,0.05466835,0.0061179893,0.03477594,-0.037208825,0.030911947,0.002128774,-0.013667087,0.061823893,-0.018747523,-0.025473733,-0.01767419,0.08586652,-0.05838923,-0.017602636,-0.005903323,0.029051505,0.030196391,0.0015831639,-0.007871097,0.018604413,0.027334174,0.010733315,0.0089444285,-0.09559806,0.009159095,-0.060965225,-0.006761988,-0.034632828,-0.0150981955,0.037495047,0.019176856,-0.04493681,0.034203496,-0.050375022,0.035491493,-0.04293326,0.032199945,0.016958637,-0.028622173,0.027477285,0.0013327199,-0.005760212,0.019176856,0.012665311,-0.020464852,0.020178631,-0.017459525,-0.0048657693,-0.028479062,-0.020751074,-0.034632