03,0.02111272,-0.026355475,-0.051010597,0.028906006,0.013177738,0.008253798,-0.01346113,0.0019483215,0.016153356,0.027347349,-0.0037372347,0.0059512365,0.008891431,0.0035246906,0.047043107,-0.0060929325,0.020971024,-0.010131272,0.013744522,0.006907685,0.022813072,0.02252968,-0.0218212,-0.0032590104,0.05356113,-0.003861219,0.011902473,0.027205652,-0.02947279,-0.045342755,-0.010060424,0.03414876,0.07934982,0.0001322866,0.011123144,0.03967491,-0.005030212,-0.0002833922,-0.052144166,0.0019926014,-0.06886431,0.0070139575,0.020687632,0.030889751,0.025363604,0.029897878,-0.025363604,-0.018987278,-0.035565723,-0.017286925,0.00765159,0.03740777,0.0030996024,-0.0010582928,0.03528233,-0.03967491,-0.016861837,0.03712438,0.002745362,0.039958302,0.043925792,0.014169611,-0.05271095,-0.016507596,-0.03429046,0.003861219,0.0002645732,-0.019554062,0.038824733,0.0018420494,0.027347349,-0.035849117,0.0071556536,0.08898515,-0.036840986,-0.0023379857,0.0150197875,-0.06121272,0.05157738,-0.029331094,0.031881623,-0.018137101,-0.012256714,0.023946643,0.02692226,0.019412367,-0.044492576,0.037691165,0.054978088,-0.05611166,0.031598233,0.021396112,-0.022387985,-0.009351943,0.0047468194,-0.0023911218,-0.0327318,-0.013744522,0.017216077,-0.010627208,0.020687632,0.012185865,0.071981624,-0.014098763,-0.040241696,-0.010981448,0.0218212,-0.036557596,0.0654636,0.020120848,-0.037691165,-0.04222544,0.031739928,-0.051860776,-0.009493639,0.020829327,-0.010981448,0.005207332,-0.015374027,-0.013177738,0.02947279,0.0031527383,-0.029189399,-0.02763074,-0.04590954,0.027914133,-0.0060220845,-0.00765159,-0.017995406,-0.029756183,-0.009068551,-0.08105017,0.0007837566,0.0074744695,-0.06801413,0.014027915,-0.040241696,0.0054553,-0.014807243,0.0010538648,-0.009422791,0.072548404,0.0014700971,0.02763074,-0.040241696,-0.005419876,0.021962896,-0.024513427,-0.0218212,0.00015165911,0.02763074,0.021396112,0.03414876,0.054694697,-0.014098763,-0.026638867,-0.0004095903,0.004233171,-0.046759713,-0.0218212]', 'xop3qwen8bembed