,-0.046354182,-0.015262962,-0.038157407,0.013567078,-0.07292304,-0.02656886,0.022894444,0.045788888,-0.023035768,0.012083178,0.0058649345,0.0028971364,0.009398028,0.020915912,-0.0021640195,-0.018796057,0.0057942728,0.011093913,-0.040418588,0.016888184,0.0054762946,0.009963322,0.001819543,0.01059928,0.00946869,-0.05426831,0.0069955243,0.026427537,-0.037026815,-0.037026815,0.0028971364,-0.025296947,-0.0017400484,-0.023742387,0.017170833,-0.0091860425,-0.047202125,0.044093,-0.0038864026,0.008903394,0.06274773,0.080837175,-0.013496416,0.053703018,-0.018796057,0.009680675,-0.007101517,0.06698745,0.055116255,0.010033985,0.053703018,0.06218244,-0.035896227,-0.015050977,-0.011729869,0.04013594,-0.022611797,0.015474948,0.009044719,-0.0041867155,-0.014061711,0.017594803,-0.050593894,-0.015050977,0.0030031293,-0.011659208,0.023601063,0.0500286,-0.04013594,-0.030949896,-0.041549176,0.020209294,0.013920387,-0.019785322,0.03787476,0.055116255,0.071227156,-0.031515192,-0.017877452,0.03674417,-0.03420034,-0.045223594,0.02883004,0.005935597,0.0075961505,-0.0075608194,0.019220026,-0.004010061,-0.025862241,0.007242841,-0.0049463306,0.03448299,0.041549176,0.035189606,0.053703018,-0.05766008,0.024590328,-0.0553989,-0.0032504457,0.008974057,-0.058508024,-0.024166357,0.02388371,-0.076880105,-0.015333625,0.0013425754,-0.063030384,-0.028971365,0.049463306,-0.02049194,-0.07150981,-0.02614489,0.009256704,0.019502675,0.04211447,0.0027381473,-0.059638612,-0.018372085,0.060769204,-0.04974595,-0.02119856,-0.031232543,0.007949459,-0.004222046,0.014909653,-0.012224503,0.0037627441,-0.03264578,0.033917695,-0.0011659208,-0.076880105,0.031939164,0.019220026,0.04098388,-0.109101914,-0.043527707,0.019643998,0.009963322,-0.029536659,0.013991049,-0.017029509,-0.0333524,-0.014909653,0.027840775,0.03674417,-0.071227156,0.024166357,-0.03066725,-0.0066068843,0.0037980753,0.030384602,0.03985329,0.012295164,-0.0007154514,-0.012295164,-0.047484774,0.0387227,0.004434032,-0.0014927319,0.0250143,0.004769676,-0.0097