,-0.017459929,0.04552305,0.01950988,-0.04495755,-0.020075383,-0.0111687,-0.034637105,-0.05824689,0.04665406,-0.023468407,-0.030819954,-0.007917053,-0.0034106947,-0.028133811,0.022478774,0.0223374,-0.038454257,-0.0033223345,-0.021489143,0.022196023,0.030395826,0.04099902,0.06022615,0.0053015975,-0.036757745,0.037323248,0.023044279,-0.024175286,0.039585263,0.030819954,0.028699316,-0.02021676,0.013501402,0.01774268,0.012299707,0.042695533,0.0035520706,-0.0061851973,-0.056550376,-0.021347767,-0.03590949,-0.017459929,0.06842595,0.054005608,0.03590949,0.00975494,0.054571114,0.012229019,0.016823737,-0.047502317,0.022902902,-0.1046182,0.074646495,0.028982067,0.009189436,0.0223374,-0.03195096,-0.063336425,-0.074080996,0.00487747,-0.020923639,0.006892077,0.0042059342,-0.0037287904,-0.002332703,0.032940593,-0.002332703,-0.028133811,-0.026013173,-0.008906684,0.0299717,-0.009330812,0.014632409,0.013501402,-0.035626736,-0.03449573,0.043826543,-0.026720053,-0.04241278,-0.042695533,-0.020358136,0.04552305,-0.0057610697,-0.04099902,0.08878409,-0.07181898,-0.087653086,0.079170525,0.0057610697,0.013854842,-0.031244082,0.011098011,0.08086704,-0.004948158,-0.0019615912,0.0040822304,0.031668212,0.020075383,0.026578676,0.0094015,-0.047502317,0.015622041,-0.052026346,-0.015409977,0.03138546,-0.097266644,-0.032516465,-0.01498585,-0.019934008,-0.032233715,0.00470075,-0.045805804,-0.044392046,0.055984873,0.019651257,-0.078605026,-0.022761526,0.017035801,0.06870871,0.0031102707,-0.036757745,-0.011239387,-0.034637105,0.074646495,-0.032940593,-0.0446748,-0.0032516466,-0.00020985492,0.032940593,0.083694555,0.029547572,0.050612587,-0.00869462,0.010744572,-0.0057610697,-0.0016788393,0.037323248,-0.08652207,-0.015622041,-0.036757745,-0.050329834,-0.0090480605,-0.048350573,-0.013430715,-0.017530616,-0.037040498,0.024882166,-0.0035874145,0.0018378872,0.0446748,-0.053440105,0.047502317,0.0523091,-0.013006587,0.036050864,0.01427897,-0.035343986,-0.0111687,-0.0027745028,-0.060508903,0.010037691,0.0294061